'use strict';
const beforeLiveRender=render;let liveState=null,operator=false,liveMessage='',livePreview=null,lastCueRequest=null,liveRefreshBusy=false;
async function liveApi(route,body,key){const r=await fetch('/api/show/'+route,body?{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':key||crypto.randomUUID()},body:JSON.stringify(body)}:{});const d=await r.json();if(!r.ok)throw Error(d.error||'演出服务请求失败');return d;}
async function loadLive(){if(liveRefreshBusy)return;liveRefreshBusy=true;try{const a=await liveApi('session');operator=a.operator;liveState=await liveApi('state');}catch(e){liveMessage=e.message;}finally{liveRefreshBusy=false;if(page==='真实演出闭环')render();}}
function liveButton(title,action,allowed=true,cls=''){return `<button data-live="${action}" class="${cls}" ${allowed&&operator&&!liveState?.busy?'':'disabled'}>${title}</button>`;}
render=function(){if(page!=='真实演出闭环'){beforeLiveRender();document.getElementById('nav').innerHTML+='<button data-page="真实演出闭环">真实演出闭环</button>';return;}document.getElementById('nav').innerHTML=['演出控制','节目编排','真实集成','真实演出闭环','执行报告','组件接入'].map(x=>`<button data-page="${x}" class="${page===x?'active':''}">${x}</button>`).join('');app.innerHTML=`<div class="eyebrow">演出自动化 / 服务端时间轴</div><h1>真实 OBS 演出闭环</h1><div class="notice">真实 OBS 软件播放与场景切换 · SQLite 保存版本、指令和回执 · 灯光、实体摄像机与自动调音未接入。预演素材由 FFmpeg 程序渲染，不是 AI 生成视频。Render 部署使用本机出站网关。</div><div id="live-content"></div>`;const c=document.getElementById('live-content');if(!liveState){c.innerHTML='<div class="card">正在读取演出状态…</div>';return;}
const s=liveState,active=['运行中','播放收尾','故障暂停','人工接管'].includes(s.status),n=s.published?.cues?.length||s.cues.length;
c.innerHTML=`<div class="row between"><p>状态：<b>${esc(s.status)}</b> · 版本 v${s.version} · ${s.transport==='gateway'?'本机出站网关':'本机直连 OBS'}</p><div class="row"><button data-live="refresh" class="secondary">刷新</button>${operator?'<button data-live="logout" class="secondary">退出操作员</button>':''}</div></div>${!operator?`<div class="card"><h2>操作员登录</h2><p class="muted">本机测试密码 demo123!；Render 使用独立配置的操作员密码。未登录可以查看状态，不能控制 OBS。</p><form id="live-login" class="row"><input name="password" type="password" required autocomplete="current-password" style="width:280px"><button>登录操作员</button></form></div>`:''}<p role="status">${esc(liveMessage)}</p><div class="stats"><div class="stat"><span>cue 回读完成</span><strong>${s.cursor} / ${n}</strong></div><div class="stat"><span>故障次数</span><strong>${s.run?.failures||0}</strong></div><div class="stat"><span>计划时长</span><strong>${((s.cues.at(-1).atMs+s.cues.at(-1).durationMs)/1000).toFixed(0)} 秒</strong></div><div class="stat"><span>网关心跳</span><strong style="font-size:1.2rem">${s.transport==='direct'?'直连模式':s.gatewayLastSeen?new Date(s.gatewayLastSeen).toLocaleTimeString('zh-CN'):'未连接'}</strong></div></div><div class="grid"><section><div class="card"><h2>准备、预检与执行</h2><div class="step">准备场景 → 真实预检 → 发布 → 自动或手动执行 → 最后媒体结束 → 报告</div><div class="row">${liveButton('准备真实 OBS 场景','prepare',!active)}${liveButton('真实软件预检','rehearse',!active)}${liveButton('发布版本','publish',s.status==='排练通过')}${liveButton('按时间轴自动开演','start-auto',s.status==='已发布')}${liveButton('手动触发开演','start-manual',s.status==='已发布')}${liveButton('执行下一条 cue','next',s.status==='运行中')}${liveButton('暂停时间轴','pause',['运行中','播放收尾'].includes(s.status),'secondary')}${liveButton('回读并恢复','recover',['故障暂停','人工接管'].includes(s.status))}${liveButton('人工接管','takeover',['运行中','故障暂停','播放收尾'].includes(s.status),'secondary')}${liveButton('终止本场','stop',active,'danger')}${liveButton('注入一次测试失败','fault',s.status==='运行中'&&s.faultInjectionAllowed,'secondary')}${liveButton('重放上一 cue 请求','replay',Boolean(lastCueRequest),'secondary')}</div><p class="muted">故障后不会跳过未确认的 cue。重复请求使用同一操作键，不会重复前进。暂停后恢复会平移后续时间轴。</p></div><div class="card"><h2>节目时间轴</h2>${s.cues.map((q,i)=>`<div class="item"><div class="row between"><b>${esc(q.name)}</b><span class="badge">${i<s.cursor?'已回读':(q.atMs/1000)+' 秒'}</span></div><p class="muted">${esc(q.sceneName)} · ${q.durationMs/1000} 秒 · ${esc(q.id)}</p></div>`).join('')}<form id="live-edit"><label><span>cue JSON（保存后需重新预检发布）</span><textarea name="cues" rows="8" ${active?'disabled':''}>${esc(JSON.stringify(s.cues,null,2))}</textarea></label><button ${operator&&!active?'':'disabled'}>保存时间轴</button></form></div><div class="card"><h2>可播放预演素材</h2><video controls preload="metadata" style="width:100%;border-radius:8px" src="/media/opening.mp4"></video><p class="muted">此文件是真实 MP4 程序渲染素材，OBS 使用同一组媒体文件。</p></div></section><section><div class="card"><h2>OBS 实际输出预览</h2>${liveButton('获取实际 OBS 画面','preview',true,'secondary')}${livePreview?`<img alt="真实 OBS 输出画面" src="${esc(livePreview.imageData)}" style="width:100%;margin-top:16px;border-radius:8px"><p class="muted">场景 ${esc(livePreview.scene)} · ${esc(livePreview.capturedAt)}</p>`:'<p class="muted">登录后从 OBS 获取实际画面，非浏览器占位图。</p>'}</div><div class="card"><h2>本场执行回执</h2>${s.run?`<p class="muted">场次 ${esc(s.run.id)} · ${s.run.auto?'自动时间轴':'手动触发'}</p><div class="scroll"><table><thead><tr><th>cue</th><th>软件回读耗时</th><th>计划偏差</th><th>恢复确认</th></tr></thead><tbody>${s.run.executions.map(e=>`<tr><td>${esc(e.name)}</td><td>${e.latencyMs} ms</td><td>${e.latenessMs} ms</td><td>${e.recovered?'是':'否'}</td></tr>`).join('')}</tbody></table></div><p class="muted">回读耗时包含连接与 API 往返，不是音视频端到端延迟；恢复回读记录的 0 ms 不计入延迟评估。</p><button data-live="download" class="secondary">下载本场报告</button>`:'<p class="muted">尚未开演。</p>'}</div><div class="card"><h2>服务端事件</h2>${s.events.slice(0,15).map(e=>`<div class="item">${esc(e.message)}<div class="muted">${esc(e.at)}</div></div>`).join('')}</div></section></div>`;};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page==='真实演出闭环'){e.stopImmediatePropagation();page='真实演出闭环';render();await loadLive();return;}if(!b.dataset.live)return;e.stopImmediatePropagation();const action=b.dataset.live;b.disabled=true;try{if(action==='refresh'){await loadLive();return;}if(action==='download'){const u=URL.createObjectURL(new Blob([JSON.stringify(liveState,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='real-show-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);return;}if(action==='logout'){await liveApi('logout',{});operator=false;liveMessage='已退出';}else if(action==='preview'){livePreview={...await liveApi('preview'),capturedAt:new Date().toLocaleString('zh-CN')};}else{let request;if(action==='replay'){request=lastCueRequest;if(!request)throw Error('还没有可重放的 cue 请求');}else request={action:action.startsWith('start-')?'start':action,body:action.startsWith('start-')?{auto:action==='start-auto'}:{},key:crypto.randomUUID()};await liveApi('actions/'+request.action,request.body,request.key);if(request.action==='next')lastCueRequest=request;liveMessage=action==='replay'?'同一请求已重放，执行进度没有重复前进':'操作已完成并保存到服务端';}await loadLive();}catch(err){liveMessage=err.message;await loadLive();}finally{if(page==='真实演出闭环')render();}},true);
document.addEventListener('submit',async e=>{if(!['live-login','live-edit'].includes(e.target.id))return;e.preventDefault();e.stopImmediatePropagation();const id=e.target.id,form=new FormData(e.target);try{if(id==='live-login'){await liveApi('login',{password:form.get('password')});operator=true;liveMessage='操作员已登录';}else{await liveApi('actions/edit',{cues:JSON.parse(form.get('cues'))});liveMessage='时间轴已更新，请重新预检和发布';}await loadLive();}catch(err){liveMessage=err.message;render();}},true);
setInterval(()=>{if(page==='真实演出闭环'&&liveState&&['运行中','播放收尾'].includes(liveState.status))loadLive();},1000);
page='真实演出闭环';render();loadLive();
